inline EntityDescriptor JsonGraphRow::entity_descriptor(Memory r) {
    EntityDescriptor d(std::allocator_arg, Allocator(r), ENTITY_NAME);
    d.table("json_graph_row_data");
    d.service("sqlite");
    {
        auto& property = d.property("id", DataType::U64, "id").id().not_null();
        (void)property;
    }
    {
        auto& property = d.property("name", DataType::Text, "name").not_null();
        property.with_max_length(100);
        (void)property;
    }
    {
        auto& property = d.property("version", DataType::I64, "version").version().not_null();
        (void)property;
    }
    {
        auto& property = d.property("platform_id", DataType::U64, "platform").not_null();
        (void)property;
    }
    {
        auto& property = d.property("peer_id", DataType::U64, "peer");
        (void)property;
    }
    {
        auto& property = d.property("single_peer_id", DataType::U64, "single_peer");
        (void)property;
    }
    {
        auto& relation = d.relation("platform", "Platform");
        relation.local_key = "platform_id";
        relation.foreign_key = "id";
        relation.many = false;
    }
    {
        auto& relation = d.relation("peer", "JsonGraphRow");
        relation.local_key = "peer_id";
        relation.foreign_key = "id";
        relation.many = false;
    }
    {
        auto& relation = d.relation("single_peer", "JsonGraphRow");
        relation.local_key = "single_peer_id";
        relation.foreign_key = "id";
        relation.many = false;
    }
    {
        auto& relation = d.relation("single_child", "JsonGraphRow");
        relation.local_key = "id";
        relation.foreign_key = "single_peer_id";
        relation.many = false;
    }
    {
        auto& relation = d.relation("child_rows", "JsonGraphRow");
        relation.local_key = "id";
        relation.foreign_key = "peer_id";
        relation.many = true;
    }
    {
        auto& relation = d.relation("parents", "SerializationParent");
        relation.local_key = "id";
        relation.foreign_key = "child_id";
        relation.many = true;
    }
    {
        auto& relation = d.relation("boxed_parents", "SerializationParent");
        relation.local_key = "id";
        relation.foreign_key = "boxed_child_id";
        relation.many = true;
    }
    d.mask_fields({});
    return d;
}

inline Result<JsonGraphRow, EntityError> JsonGraphRow::from_compact_row(Memory r, CompactRow row) {
    using Outcome = Result<JsonGraphRow, EntityError>;
    JsonGraphRow result(std::allocator_arg, Allocator(r));
    auto captured =
        detail::EntityRuntimeAccess::capture_dynamic_values(result.dynamic, row, field_layout(r));
    if (!captured) {
        return Outcome::err(r, std::move(captured).error());
    }
    ArenaBorrow<FieldLayout> field_layout_binding(
        std::allocator_arg, Allocator(r), field_layout(r));
    auto id_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "id", "id", false, field_layout_binding);
    if (!id_lookup) {
        return Outcome::err(r, std::move(id_lookup).error());
    }
    auto platform_id_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "platform_id", "platform", true, field_layout_binding);
    if (!platform_id_lookup) {
        return Outcome::err(r, std::move(platform_id_lookup).error());
    }
    auto name_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "name", "name", false, field_layout_binding);
    if (!name_lookup) {
        return Outcome::err(r, std::move(name_lookup).error());
    }
    auto peer_id_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "peer_id", "peer", true, field_layout_binding);
    if (!peer_id_lookup) {
        return Outcome::err(r, std::move(peer_id_lookup).error());
    }
    auto single_peer_id_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "single_peer_id", "single_peer", true, field_layout_binding);
    if (!single_peer_id_lookup) {
        return Outcome::err(r, std::move(single_peer_id_lookup).error());
    }
    auto version_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "version", "version", false, field_layout_binding);
    if (!version_lookup) {
        return Outcome::err(r, std::move(version_lookup).error());
    }
    auto id_value =
        generated_detail::decode<std::uint64_t>(r, id_lookup.value().value, ENTITY_NAME, "id");
    if (!id_value) {
        return Outcome::err(r, std::move(id_value).error());
    }
    result.id_ = std::move(id_value).value();
    auto platform_id_value = generated_detail::decode<std::uint64_t>(
        r, platform_id_lookup.value().value, ENTITY_NAME, "platform_id");
    if (!platform_id_value) {
        return Outcome::err(r, std::move(platform_id_value).error());
    }
    result.platform_id_ = std::move(platform_id_value).value();
    auto name_value =
        generated_detail::decode<String>(r, name_lookup.value().value, ENTITY_NAME, "name");
    if (!name_value) {
        return Outcome::err(r, std::move(name_value).error());
    }
    result.name_ = std::move(name_value).value();
    auto peer_id_value = generated_detail::decode<std::optional<std::uint64_t>>(
        r, peer_id_lookup.value().value, ENTITY_NAME, "peer_id");
    if (!peer_id_value) {
        return Outcome::err(r, std::move(peer_id_value).error());
    }
    result.peer_id_ = std::move(peer_id_value).value();
    auto single_peer_id_value = generated_detail::decode<std::optional<std::uint64_t>>(
        r, single_peer_id_lookup.value().value, ENTITY_NAME, "single_peer_id");
    if (!single_peer_id_value) {
        return Outcome::err(r, std::move(single_peer_id_value).error());
    }
    result.single_peer_id_ = std::move(single_peer_id_value).value();
    auto version_value = generated_detail::decode<std::int64_t>(
        r, version_lookup.value().value, ENTITY_NAME, "version");
    if (!version_value) {
        return Outcome::err(r, std::move(version_value).error());
    }
    result.version_ = std::move(version_value).value();
    auto platform_decoded = GeneratedRelationAccess::decodeObject<Platform>(r, row.get("platform"));
    if (!platform_decoded) {
        return Outcome::err(r, std::move(platform_decoded).error());
    }
    if (platform_decoded.value()) {
        result.platform_ = detail::make_box<Platform>(r, std::move(*platform_decoded.value()));
    }
    auto peer_decoded = GeneratedRelationAccess::decodeObject<JsonGraphRow>(r, row.get("peer"));
    if (!peer_decoded) {
        return Outcome::err(r, std::move(peer_decoded).error());
    }
    if (peer_decoded.value()) {
        result.peer_ = detail::make_box<JsonGraphRow>(r, std::move(*peer_decoded.value()));
    }
    auto single_peer_decoded =
        GeneratedRelationAccess::decodeObject<JsonGraphRow>(r, row.get("single_peer"));
    if (!single_peer_decoded) {
        return Outcome::err(r, std::move(single_peer_decoded).error());
    }
    if (single_peer_decoded.value()) {
        result.single_peer_ =
            detail::make_box<JsonGraphRow>(r, std::move(*single_peer_decoded.value()));
    }
    result.load_state = row.indexed_load_state(
        detail::ContextArena::from_memory(r).loaded_snapshots(), field_layout(r));
    if (platform_id_lookup.value().alias_present) {
        auto& pool = detail::ContextArena::from_memory(r).loaded_snapshots();
        if (!platform_id_lookup.value().object_alias && !row.is_loaded_relation("platform")) {
            result.load_state.mark_unloaded("platform", &pool).value();
        }
        result.load_state.mark_loaded("platform_id", &pool).value();
    }
    if (peer_id_lookup.value().alias_present) {
        auto& pool = detail::ContextArena::from_memory(r).loaded_snapshots();
        if (!peer_id_lookup.value().object_alias && !row.is_loaded_relation("peer")) {
            result.load_state.mark_unloaded("peer", &pool).value();
        }
        result.load_state.mark_loaded("peer_id", &pool).value();
    }
    if (single_peer_id_lookup.value().alias_present) {
        auto& pool = detail::ContextArena::from_memory(r).loaded_snapshots();
        if (!single_peer_id_lookup.value().object_alias && !row.is_loaded_relation("single_peer")) {
            result.load_state.mark_unloaded("single_peer", &pool).value();
        }
        result.load_state.mark_loaded("single_peer_id", &pool).value();
    }
    result.root.set_original_compact_row(ENTITY_NAME, std::move(row));
    return Outcome::ok(r, std::move(result));
}

inline MutationValues JsonGraphRow::into_values() && {
    auto r = memory_resource();
    MutationValues values(r);
    values.fields.emplace(String("id", r), generated_detail::encode(r, id_));
    values.fields.emplace(String("platform_id", r), generated_detail::encode(r, platform_id_));
    values.fields.emplace(String("name", r), generated_detail::encode(r, name_));
    values.fields.emplace(String("peer_id", r), generated_detail::encode(r, peer_id_));
    values.fields.emplace(String("single_peer_id", r),
                          generated_detail::encode(r, single_peer_id_));
    values.fields.emplace(String("version", r), generated_detail::encode(r, version_));
    detail::EntityRuntimeAccess::retain_loaded_native_values(values, load_state);
    if (platform_) {
        values.fields.emplace(String("platform", r),
                              Value(r, std::move(*platform_).into_values().fields));
    }
    if (peer_) {
        values.fields.emplace(String("peer", r), Value(r, std::move(*peer_).into_values().fields));
    }
    if (single_peer_) {
        values.fields.emplace(String("single_peer", r),
                              Value(r, std::move(*single_peer_).into_values().fields));
    }
    if (auto relation = std::move(child_rows_).into_value()) {
        values.fields.emplace(String("child_rows", r), std::move(*relation));
    }
    if (single_child_) {
        values.fields.emplace(String("single_child", r),
                              Value(r, std::move(*single_child_).into_values().fields));
    }
    if (auto relation = std::move(parents_).into_value()) {
        values.fields.emplace(String("parents", r), std::move(*relation));
    }
    if (auto relation = std::move(boxed_parents_).into_value()) {
        values.fields.emplace(String("boxed_parents", r), std::move(*relation));
    }
    inject_runtime(values);
    return values;
}

