inline MutationValues SerializationParent::into_values() && {
    auto r = memory_resource();
    MutationValues values(r);
    values.fields.emplace(String("id", r), generated_detail::encode(r, id_));
    values.fields.emplace(String("platform_id", r), generated_detail::encode(r, platform_id_));
    values.fields.emplace(String("name", r), generated_detail::encode(r, name_));
    values.fields.emplace(String("child_id", r), generated_detail::encode(r, child_id_));
    values.fields.emplace(String("boxed_child_id", r),
                          generated_detail::encode(r, boxed_child_id_));
    values.fields.emplace(String("version", r), generated_detail::encode(r, version_));
    detail::EntityRuntimeAccess::retain_loaded_native_values(values, load_state);
    if (platform_) {
        values.fields.emplace(String("platform", r),
                              Value(r, std::move(*platform_).into_values().fields));
    }
    if (child_) {
        values.fields.emplace(String("child", r),
                              Value(r, std::move(*child_).into_values().fields));
    }
    if (boxed_child_) {
        values.fields.emplace(String("boxed_child", r),
                              Value(r, std::move(*boxed_child_).into_values().fields));
    }
    if (auto relation = std::move(child_rows_).into_value()) {
        values.fields.emplace(String("child_rows", r), std::move(*relation));
    }
    if (auto relation = std::move(boxed_children_).into_value()) {
        values.fields.emplace(String("boxed_children", r), std::move(*relation));
    }
    inject_runtime(values);
    return values;
}

inline SerializationParent& SerializationParent::updatePlatform(const Platform& value) {
    platform_ = detail::make_box<Platform>(memory_resource(), value);
    updatePlatformId(value.id());
    return *this;
}

inline SerializationParent& SerializationParent::updateChild(const JsonGraphRow& value) {
    child_ = detail::make_box<JsonGraphRow>(memory_resource(), value);
    updateChildId(value.id());
    return *this;
}

inline SerializationParent& SerializationParent::updateBoxedChild(const JsonGraphRow& value) {
    boxed_child_ = detail::make_box<JsonGraphRow>(memory_resource(), value);
    updateBoxedChildId(value.id());
    return *this;
}

inline const Platform* SerializationMember::platform() const {
    if (platform_) {
        return platform_.get();
    }
    if (!is_loaded("platform")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<Platform>("serialization_member", id(), "platform");
    if (view) {
        return *view ? &**view : nullptr;
    }
    return root.resolve_entity<Platform>(platformId());
}

inline const SerializationParent* SerializationMember::parent() const {
    if (parent_) {
        return parent_.get();
    }
    if (!is_loaded("parent")) {
        return nullptr;
    }
    auto* view =
        root.resolve_relation_option<SerializationParent>("serialization_member", id(), "parent");
    if (view) {
        return *view ? &**view : nullptr;
    }
    auto foreign = parentId();
    return foreign ? root.resolve_entity<SerializationParent>(*foreign) : nullptr;
}

inline const SerializationParent* SerializationMember::boxedParent() const {
    if (boxed_parent_) {
        return boxed_parent_.get();
    }
    if (!is_loaded("boxed_parent")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<SerializationParent>(
        "serialization_member", id(), "boxed_parent");
    if (view) {
        return *view ? &**view : nullptr;
    }
    auto foreign = boxedParentId();
    return foreign ? root.resolve_entity<SerializationParent>(*foreign) : nullptr;
}

inline eval::EvalResult<EntityBorrow<Platform>> SerializationMember::evalPlatform() const {
    return GeneratedRelationAccess::object(memory_resource(), "platform", platform(), false);
}

inline eval::EvalResult<EntityBorrow<SerializationParent>> SerializationMember::evalParent() const {
    return GeneratedRelationAccess::object(
        memory_resource(), "parent", parent(), is_loaded("parent_id") && !parentId());
}

inline eval::EvalResult<EntityBorrow<SerializationParent>>
SerializationMember::evalBoxedParent() const {
    return GeneratedRelationAccess::object(memory_resource(),
                                           "boxed_parent",
                                           boxedParent(),
                                           is_loaded("boxed_parent_id") && !boxedParentId());
}

inline std::optional<Json>
SerializationMember::borrowed_json(Memory r, EntityJsonTraversal& traversal) const {
    GeneratedEntityJson projection(r, traversal, ENTITY_NAME, this, root, id_for_runtime());
    projection.field(
        "id",
        [&] {
            return generated_detail::encode(r, id_);
        },
        load_state.is_loaded("id"),
        true);
    projection.field(
        "platform_id",
        [&] {
            return generated_detail::encode(r, platform_id_);
        },
        load_state.is_loaded("platform_id"),
        false);
    projection.field(
        "name",
        [&] {
            return generated_detail::encode(r, name_);
        },
        load_state.is_loaded("name"),
        false);
    projection.field(
        "parent_id",
        [&] {
            return generated_detail::encode(r, parent_id_);
        },
        load_state.is_loaded("parent_id"),
        false);
    projection.field(
        "boxed_parent_id",
        [&] {
            return generated_detail::encode(r, boxed_parent_id_);
        },
        load_state.is_loaded("boxed_parent_id"),
        false);
    projection.field(
        "version",
        [&] {
            return generated_detail::encode(r, version_);
        },
        load_state.is_loaded("version"),
        true);
    projection.dynamic(dynamic);
    projection.forward<Platform>("platform",
                                 platform_ ? &*platform_ : nullptr,
                                 load_state.is_loaded("platform"),
                                 generated_detail::encode(r, platform_id_));
    projection.forward<SerializationParent>("parent",
                                            parent_ ? &*parent_ : nullptr,
                                            load_state.is_loaded("parent"),
                                            generated_detail::encode(r, parent_id_));
    projection.forward<SerializationParent>("boxed_parent",
                                            boxed_parent_ ? &*boxed_parent_ : nullptr,
                                            load_state.is_loaded("boxed_parent"),
                                            generated_detail::encode(r, boxed_parent_id_));
    return projection.finish(dynamic_field_values());
}

inline void SerializationMember::attachRuntimeStateRecursive(const EntityRuntimeState& target) {
    root.attach_runtime_state(target);
    if (platform_) {
        platform_->attachRuntimeStateRecursive(target);
    }
    if (parent_) {
        parent_->attachRuntimeStateRecursive(target);
    }
    if (boxed_parent_) {
        boxed_parent_->attachRuntimeStateRecursive(target);
    }
}

